import {createApi} from './focus-api.mjs';import {esc} from './customer-shared.mjs';
const api=createApi(),box=document.querySelector('#account'),status=document.querySelector('#status');const invite=new URLSearchParams(location.hash.slice(1)).get('invite');if(invite){sessionStorage.setItem('paytrace-pending-invite',invite);history.replaceState(null,'',location.pathname);}
async function init(){try{const d=await api('auth/session');if(d.account){box.innerHTML=`<h2>Your verified merchant account</h2><p>${esc(d.account.email)}</p><span class="pill">${esc(d.account.role||'Membership invitation needed')}</span>${d.account.memberships.length?`<form><label>Workspace<select name="owner">${d.account.memberships.map(m=>`<option value="${esc(m.owner)}" ${m.owner===d.account.owner?'selected':''}>${esc(m.owner)} · ${esc(m.role)}</option>`).join('')}</select></label><p><button>Switch workspace</button> <a class="button primary" href="focus.html">Open recovery desk</a></p></form>`:'<p>Ask your workspace administrator for an invitation addressed to this verified email.</p>'}<div class="actions"><button id="sign-out">Sign out</button>${d.accountUrl?`<a class="button" href="${esc(d.accountUrl)}" rel="noreferrer">Manage password & MFA ↗</a>`:''}</div><p class="notice">Passwords and account recovery are handled by your identity provider. PayTrace does not store passwords. Sessions expire after inactivity or their absolute limit.</p>`;const f=box.querySelector('form');if(f)f.onsubmit=async e=>{e.preventDefault();try{await api('auth/workspace',{owner:new FormData(f).get('owner')});location.href='recovery.html';}catch(e){status.textContent=e.message;}};box.querySelector('#sign-out').onclick=async()=>{await api('auth/logout',{});location.reload();};const token=sessionStorage.getItem('paytrace-pending-invite');if(token){const p=document.createElement('div');p.innerHTML='<h3>Workspace invitation</h3><p>Accept this invitation with the verified email it was issued to.</p><button>Accept membership invitation</button>';box.append(p);p.querySelector('button').onclick=async e=>{e.target.disabled=true;try{await api('auth/accept',{token});sessionStorage.removeItem('paytrace-pending-invite');location.href='recovery.html';}catch(err){status.textContent=err.message;e.target.disabled=false;}};}return;}
 box.innerHTML=d.configured?`<h2>Use your verified business account</h2><p>Sign in through the configured identity provider. ${d.requireMfa?'Multi-factor authentication and a verified email are required.':''}</p><p><a class="button primary" href="/auth/login">Sign in securely</a></p>${d.accountUrl?`<p><a href="${esc(d.accountUrl)}" rel="noreferrer">Recover your account or manage MFA ↗</a></p>`:''}`:'<h2>Verified sign-in needs server setup</h2><p>Configure the OIDC issuer, client and administrator allowlist. No local password form is enabled.</p><p><a class="button" href="recovery.html">Return to the demo workspace</a></p>';if(!d.required)box.insertAdjacentHTML('beforeend','<p class="notice">This server is currently in demonstration mode. Demo sessions are separate from verified-account workspaces.</p>');
 }catch(e){status.textContent=e.message;box.innerHTML='<h2>Account service unavailable</h2><button>Retry account check</button>';box.querySelector('button').onclick=init;}}init();
